SELECT b.id,r.id,current_date - v.days_ago,current_date - v.days_ago + 14,
 CASE WHEN v.done THEN current_date-v.days_ago+10 ELSE NULL END,b.title,b.author,r.name,r.class
FROM (VALUES (1,1,4,false),(5,2,6,false),(4,3,2,false),(3,4,23,false),(6,5,19,false),(12,6,5,false),
(7,7,30,false),(2,8,1,false),(17,9,8,false),(21,10,22,false),
(1,2,36,true),(1,3,65,true),(5,1,42,true),(4,5,74,true),(3,6,94,true),(6,7,120,true),
(12,8,150,true),(1,9,155,true),(5,10,100,true),(16,11,37,true),(2,12,68,true),
(21,1,125,true),(18,2,160,true),(4,4,45,true),(12,5,85,true),(17,6,12,true)) v(book_id,reader_id,days_ago,done)
JOIN books b ON b.id=v.book_id JOIN readers r ON r.id=v.reader_id;
UPDATE books b SET available_copies = total_copies-(SELECT count(*) FROM loans l WHERE l.book_id=b.id AND l.returned_at IS NULL);
